draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.fillStyle = '#ccc';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.fill();

  // thought bubble
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(W/2 + 150 * Math.sin(t), H/2 - 50 * Math.cos(t), 50, 0, 2 * Math.PI);
  ctx.fill();

  // stick figure
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 170);
  ctx.lineTo(W/2, H/2 + 250);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 - 50, H/2 + 220);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 + 50, H/2 + 220);
  ctx.stroke();

  // insight text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000';
  ctx.fillText('Insight', W/2 + 150 * Math.sin(t), H/2 - 50 * Math.cos(t) + 25);

  ctx.restore();
}
